SELECT revision_id INTO @revision_id FROM repository_revisions WHERE revision_code=@revision_code LIMIT 1;

DROP PROCEDURE IF EXISTS frzk_assert_348;
DELIMITER $$
CREATE PROCEDURE frzk_assert_348()
BEGIN
 IF @parent_section_id IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Übergeordneter Abschnitt 3.4 fehlt.'; END IF;
 IF @section_id IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Abschnitt 3.4.8 konnte nicht bestimmt werden.'; END IF;
 IF @source_dummit IS NULL OR @source_diestel IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Bestandsquelle [31] oder [47] fehlt.'; END IF;
END$$
DELIMITER ;
CALL frzk_assert_348();
DROP PROCEDURE frzk_assert_348;

