DELETE FROM definitions WHERE definition_number IN ('Definition 3.4.27','Definition 3.4.28','Definition 3.4.29','Definition 3.4.30','Definition 3.4.31','Definition 3.4.32','Definition 3.4.33','Definition 3.4.34','Definition 3.4.35');
INSERT INTO definitions
(definition_number,section_id,title,definition_text,formal_latex,word_latex,provenance,source_id,assumptions,validation_status,created_revision_id) VALUES
('Definition 3.4.27',@section_id,'Funktionale Erreichbarkeit','Ein kohärenter Zustand ist funktional erreichbar, wenn er durch eine endliche Folge kohärenzerhaltender Operatoren aus einem anderen kohärenten Zustand hervorgeht.','z_F^{(i)}\\leadsto_F z_F^{(j)}','z_F^{(i)}\\leadsto_F z_F^{(j)}','original',NULL,'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.','checked',@revision_id),
('Definition 3.4.28',@section_id,'Wechselseitige funktionale Erreichbarkeit','Zwei kohärente Zustände sind wechselseitig funktional erreichbar, wenn beide jeweils vom anderen erreichbar sind.','z_F^{(i)}\\leftrightsquigarrow_F z_F^{(j)}','z_F^{(i)}\\leftrightsquigarrow_F z_F^{(j)}','original',NULL,'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.','checked',@revision_id),
('Definition 3.4.29',@section_id,'Funktionale Zusammenhangskomponente','Die Äquivalenzklasse eines Zustands bezüglich der wechselseitigen funktionalen Erreichbarkeit heißt funktionale Zusammenhangskomponente.','[z_F]_{\\leftrightsquigarrow_F}','[z_F]_{\\leftrightsquigarrow_F}','original',NULL,'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.','checked',@revision_id),
('Definition 3.4.30',@section_id,'Unmittelbare funktionale Erreichbarkeit','Ein Zustand ist unmittelbar erreichbar, wenn ein einzelner kohärenzerhaltender Operator ihn erzeugt.','z_F\\to_F^{K}z_F^{\\prime}','z_F\\to_F^{K}z_F^{\\prime}','original',NULL,'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.','checked',@revision_id),
('Definition 3.4.31',@section_id,'Gerichtete funktionale Nachbarschaft','Die ausgehende beziehungsweise eingehende Nachbarschaft enthält die in einem Schritt erreichbaren Folgezustände beziehungsweise Vorgängerzustände.','\\mathcal N_F^{+}(z_F),\\mathcal N_F^{-}(z_F)','\\mathcal N_F^{+}(z_F),\\mathcal N_F^{-}(z_F)','original',NULL,'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.','checked',@revision_id),
('Definition 3.4.32',@section_id,'Funktionale Raumstruktur','Die funktionale Raumstruktur ist der kohärente Zustandsraum zusammen mit seiner Erreichbarkeits- oder unmittelbaren Übergangsrelation.','\\mathfrak R_F^{K}(\\mathcal S)=\\left(\\Omega_F^{K}(\\mathcal S),\\leadsto_F\\right)','\\mathfrak R_F^{K}(\\mathcal S)=\\left(\\Omega_F^{K}(\\mathcal S),\\leadsto_F\\right)','original',NULL,'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.','checked',@revision_id),
('Definition 3.4.33',@section_id,'Länge eines funktionalen Entwicklungspfads','Die funktionale Pfadlänge ist die Anzahl der Operatorwirkungen eines endlichen Entwicklungspfads.','\\ell_F(\\mathcal P_F^{(n)})=n','\\ell_F(\\mathcal P_F^{(n)})=n','original',NULL,'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.','checked',@revision_id),
('Definition 3.4.34',@section_id,'Funktionale Übergangsdistanz','Die funktionale Übergangsdistanz ist die minimale Länge aller gerichteten funktionalen Pfade zwischen zwei Zuständen.','\\delta_F(z_F^{(i)},z_F^{(j)})','\\delta_F(z_F^{(i)},z_F^{(j)})','original',NULL,'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.','checked',@revision_id),
('Definition 3.4.35',@section_id,'Funktionale Übergangsrichtung','Die funktionale Übergangsrichtung ist die durch einen Operator erzeugte funktionale Differenz zwischen Ausgangs- und Folgezustand.','\\vec{\\rho}_F(z_F,O_F)=\\Delta_F(z_F,O_F(z_F))','\\vec{\\rho}_F(z_F,O_F)=\\Delta_F(z_F,O_F(z_F))','original',NULL,'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.','checked',@revision_id);

DELETE FROM lemmas WHERE lemma_number IN ('Lemma 3.4.10','Lemma 3.4.11','Lemma 3.4.12','Lemma 3.4.13');
INSERT INTO lemmas
(lemma_number,section_id,title,statement_text,statement_latex,word_latex,provenance,source_id,assumptions,validation_status,created_revision_id) VALUES
('Lemma 3.4.10',@section_id,'Reflexivität der funktionalen Erreichbarkeit','Jeder kohärente Zustand ist von sich selbst funktional erreichbar.','z_F\\leadsto_F z_F','z_F\\leadsto_F z_F','original',NULL,'Definitionen 3.4.27 bis 3.4.34.','checked',@revision_id),
('Lemma 3.4.11',@section_id,'Transitivität der funktionalen Erreichbarkeit','Funktionale Erreichbarkeit ist unter der Verkettung kohärenzerhaltender Pfade transitiv.','z_F^{(i)}\\leadsto_F z_F^{(j)}\\land z_F^{(j)}\\leadsto_F z_F^{(k)}\\Longrightarrow z_F^{(i)}\\leadsto_F z_F^{(k)}','z_F^{(i)}\\leadsto_F z_F^{(j)}\\land z_F^{(j)}\\leadsto_F z_F^{(k)}\\Longrightarrow z_F^{(i)}\\leadsto_F z_F^{(k)}','original',NULL,'Definitionen 3.4.27 bis 3.4.34.','checked',@revision_id),
('Lemma 3.4.12',@section_id,'Äquivalenzrelation der wechselseitigen Erreichbarkeit','Wechselseitige funktionale Erreichbarkeit ist reflexiv, symmetrisch und transitiv.','\\leftrightsquigarrow_F\\text{ ist eine Äquivalenzrelation}','\\leftrightsquigarrow_F\\text{ ist eine Äquivalenzrelation}','original',NULL,'Definitionen 3.4.27 bis 3.4.34.','checked',@revision_id),
('Lemma 3.4.13',@section_id,'Dreiecksungleichung der funktionalen Übergangsdistanz','Die minimale funktionale Pfadlänge erfüllt die Dreiecksungleichung.','\\delta_F(z_F^{(i)},z_F^{(k)})\\leq\\delta_F(z_F^{(i)},z_F^{(j)})+\\delta_F(z_F^{(j)},z_F^{(k)})','\\delta_F(z_F^{(i)},z_F^{(k)})\\leq\\delta_F(z_F^{(i)},z_F^{(j)})+\\delta_F(z_F^{(j)},z_F^{(k)})','original',NULL,'Definitionen 3.4.27 bis 3.4.34.','checked',@revision_id);

DELETE FROM theorems WHERE theorem_number IN ('Satz 3.4.11','Satz 3.4.12','Satz 3.4.13');
INSERT INTO theorems
(theorem_number,section_id,title,statement_text,statement_latex,word_latex,provenance,source_id,assumptions,validation_status,created_revision_id) VALUES
('Satz 3.4.11',@section_id,'Präordnungsstruktur der funktionalen Erreichbarkeit','Die funktionale Erreichbarkeit bildet auf dem kohärenten Zustandsraum eine Präordnung.','\\left(\\Omega_F^{K}(\\mathcal S),\\leadsto_F\\right)','\\left(\\Omega_F^{K}(\\mathcal S),\\leadsto_F\\right)','original',NULL,'Definitionen und Lemmata des Abschnitts 3.4.8.','checked',@revision_id),
('Satz 3.4.12',@section_id,'Existenz funktionaler Raumstrukturen','Ein nichtleerer kohärenter Zustandsraum mit Identitätsoperator bestimmt eine funktionale Raumstruktur.','\\Omega_F^{K}(\\mathcal S)\\neq\\varnothing\\Longrightarrow\\mathfrak R_F^{K}(\\mathcal S)','\\Omega_F^{K}(\\mathcal S)\\neq\\varnothing\\Longrightarrow\\mathfrak R_F^{K}(\\mathcal S)','original',NULL,'Definitionen und Lemmata des Abschnitts 3.4.8.','checked',@revision_id),
('Satz 3.4.13',@section_id,'Quasimetrische Struktur der funktionalen Übergangsdistanz','Auf jeder funktionalen Zusammenhangskomponente bildet die minimale gerichtete Pfadlänge im Allgemeinen eine Quasimetrik.','\\delta_F\\text{ ist eine Quasimetrik}','\\delta_F\\text{ ist eine Quasimetrik}','adapted',@source_diestel,'Definitionen und Lemmata des Abschnitts 3.4.8.','checked',@revision_id);

