INSERT INTO corollaries
(corollary_number,section_id,title,statement_text,statement_latex,word_latex,parent_theorem_id,parent_lemma_id,provenance,source_id,validation_status,created_revision_id) VALUES
('Korollar 3.4.10',@section_id,'Raumstruktur ohne vorausgesetzte Geometrie','Aus einer funktionalen Raumstruktur folgt nicht notwendig eine Metrik, Norm oder ein Koordinatensystem.','\\mathfrak R_F^{K}(\\mathcal S)\\nRightarrow\\left(\\Omega_F^{K}(\\mathcal S),d_F\\right)','\\mathfrak R_F^{K}(\\mathcal S)\\nRightarrow\\left(\\Omega_F^{K}(\\mathcal S),d_F\\right)',@satz_3412,NULL,'original',NULL,'checked',@revision_id),
('Korollar 3.4.11',@section_id,'Metrische Struktur bei reversibler Übergangsordnung','Sind sämtliche unmittelbaren Übergänge reversibel und gleich lang, wird die funktionale Übergangsdistanz symmetrisch und damit metrisch.','\\delta_F(z_F^{(i)},z_F^{(j)})=\\delta_F(z_F^{(j)},z_F^{(i)})','\\delta_F(z_F^{(i)},z_F^{(j)})=\\delta_F(z_F^{(j)},z_F^{(i)})',@satz_3413,NULL,'original',NULL,'checked',@revision_id);

SELECT corollary_id INTO @kor_3410 FROM corollaries WHERE corollary_number='Korollar 3.4.10' LIMIT 1;
SELECT corollary_id INTO @kor_3411 FROM corollaries WHERE corollary_number='Korollar 3.4.11' LIMIT 1;

DELETE FROM proofs WHERE proof_number LIKE 'Bew. 3.4.8-R%';
INSERT INTO proofs
(proof_number,section_id,theorem_id,lemma_id,corollary_id,title,proof_text,proof_latex,proof_method,provenance,source_id,validation_status,created_revision_id) VALUES
('Bew. 3.4.8-R1',@section_id,NULL,@lemma_3410,NULL,'Beweis zu Lemma 3.4.10','Der Identitätsoperator gehört zum kohärenzerhaltenden Monoid und bildet jeden Zustand auf sich selbst ab.','I_F(z_F)=z_F','direct','original',NULL,'checked',@revision_id),
('Bew. 3.4.8-R2',@section_id,NULL,@lemma_3411,NULL,'Beweis zu Lemma 3.4.11','Zwei aufeinanderfolgende kohärenzerhaltende Pfade können durch Komposition ihrer Gesamtoperatoren zu einem kohärenzerhaltenden Pfad verkettet werden.','z_F^{(k)}=\\widetilde O_F^{[n]}\\circ O_F^{[m]}(z_F^{(i)})','direct','original',NULL,'checked',@revision_id),
('Bew. 3.4.8-R3',@section_id,@satz_3411,NULL,NULL,'Beweis zu Satz 3.4.11','Reflexivität und Transitivität folgen aus Lemma 3.4.10 und Lemma 3.4.11; damit liegt eine Präordnung vor.','(\\Omega_F^{K}(\\mathcal S),\\leadsto_F)','direct','adapted',@source_dummit,'checked',@revision_id),
('Bew. 3.4.8-R4',@section_id,NULL,@lemma_3412,NULL,'Beweis zu Lemma 3.4.12','Reflexivität und Transitivität werden von der Erreichbarkeit übernommen; Symmetrie ist Bestandteil der Definition wechselseitiger Erreichbarkeit.','\\leftrightsquigarrow_F\\text{ ist eine Äquivalenzrelation}','direct','adapted',@source_dummit,'checked',@revision_id),
('Bew. 3.4.8-R5',@section_id,@satz_3412,NULL,NULL,'Beweis zu Satz 3.4.12','Ein nichtleerer kohärenter Zustandsraum und der Identitätsoperator bestimmen mindestens eine reflexive und transitive Erreichbarkeitsrelation.','z_F\\leadsto_F z_F','direct','original',NULL,'checked',@revision_id),
('Bew. 3.4.8-R6',@section_id,NULL,@lemma_3413,NULL,'Beweis zu Lemma 3.4.13','Die Verkettung zweier kürzester Pfade liefert einen zulässigen Gesamtpfad, dessen Länge die Summe der Teillängen ist. Das Minimum kann nicht größer sein.','\\ell_F(\\mathcal P_{ik})=\\ell_F(\\mathcal P_{ij})+\\ell_F(\\mathcal P_{jk})','direct','adapted',@source_diestel,'checked',@revision_id),
('Bew. 3.4.8-R7',@section_id,@satz_3413,NULL,NULL,'Beweis zu Satz 3.4.13','Nichtnegativität, Identität der Ununterscheidbaren und Dreiecksungleichung gelten; Symmetrie ist wegen gerichteter Übergänge nicht allgemein gegeben.','\\delta_F\\text{ ist eine Quasimetrik}','direct','adapted',@source_diestel,'checked',@revision_id),
('Bew. 3.4.8-R8',@section_id,NULL,NULL,@kor_3410,'Begründung zu Korollar 3.4.10','Die Erreichbarkeitsstruktur enthält keine zusätzliche Festlegung eines numerischen Abstands, einer Norm oder von Koordinaten.','\\mathfrak R_F^{K}(\\mathcal S)\\nRightarrow(\\Omega_F^{K}(\\mathcal S),d_F)','direct','original',NULL,'checked',@revision_id),
('Bew. 3.4.8-R9',@section_id,NULL,NULL,@kor_3411,'Begründung zu Korollar 3.4.11','Reversible gleich lange Übergänge erzeugen zu jedem kürzesten Hinpfad einen gleich langen Rückpfad und damit Symmetrie.','\\delta_F(z_i,z_j)=\\delta_F(z_j,z_i)','direct','adapted',@source_diestel,'checked',@revision_id);

